-- 菜单 INSERT（由 .agents/skills/menu-generator/gen_menu_migration.mjs 自动扫描 cmx-container/data/menu-pages 生成，可重跑）
-- 模块本身由 DAM 派生（不在 cmx_menu）；此处仅各模块下的菜单 items 作为该模块菜单根节点。
-- 节点级映射：workspace/dialogspace 等富数据入 definition JSONB；跨文件冲突 code 加 _dup 后缀。
-- 幂等保证：先按 domain/application/module 删除旧数据，再插入最新（重跑 = 重置为文件最新状态）。

DELETE FROM cmx_menu WHERE domain_code = 'fi' AND application_code = 'cmxfico' AND module_code = 'gl';
DELETE FROM cmx_menu WHERE domain_code = 'fi' AND application_code = 'cmxfico' AND module_code = 'report';

